CREATE TABLE IF NOT EXISTS products (id TEXT PRIMARY KEY, name TEXT NOT NULL, category TEXT NOT NULL, brand TEXT NOT NULL, price NUMERIC(12,2) NOT NULL CHECK (price >= 0), original_price NUMERIC(12,2) NOT NULL DEFAULT 0, rating NUMERIC(2,1) NOT NULL DEFAULT 0, review_count INTEGER NOT NULL DEFAULT 0, stock_quantity INTEGER NOT NULL DEFAULT 0, badge TEXT NOT NULL DEFAULT 'FEATURED', image TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', featured BOOLEAN NOT NULL DEFAULT false, active BOOLEAN NOT NULL DEFAULT true, created_at TIMESTAMPTZ NOT NULL DEFAULT now())